public sealed class StormAtSea:MonoBehaviour {
 public enum Phase{Voyage,StormRises,Ready,Balance,Failed,Wake,Calming,Quiet}
 public Phase CurrentPhase{get;private set;}public bool InGame=>CurrentPhase==Phase.Balance||CurrentPhase==Phase.Failed;public bool IsCinematic=>CurrentPhase==Phase.StormRises||CurrentPhase==Phase.Calming;public int Stage{get;private set;}public float Survived{get;private set;}public const float Duration=20;public float SurviveDuration=>JourneyStageLayout.Current?Mathf.Max(1,JourneyStageLayout.Current.stormSurvivalSeconds):Duration;public float LateralPosition=>lateral;public float LateralVelocity=>velocity;public int Retries{get;private set;}public bool JesusAwake{get;private set;}public float StormStrength{get;private set;}public Transform Player=>player;public Transform Boat=>boat;
 JourneyGame game;Transform player,boat,water,sleeper,awakeJesus;SpriteRenderer body,sea,sky;Material mat;Sprite square,sleepSprite,hullSprite;Sprite[] waveSprites;Mesh sailMesh;Transform sail;GameObject environment,panel;Transform[] waves=new Transform[12],rain=new Transform[36],disciples=new Transform[6];Canvas ui;RectTransform marker,timeFill;TMP_Text feedback;float clock,lateral,velocity,edgeTime;bool busy,shutdown,oldPixel;UnityEngine.Rendering.Universal.PixelPerfectCamera pixel;
 public void Initialize(JourneyGame g,Transform p,SpriteRenderer b,Material m,Sprite s,int step){JourneyObjectFactory.BeginStage(this,step);game=g;player=p;body=b;mat=m;square=s;hullSprite=JourneySpriteAssets.LoadAll("CrossTheLine/GalileeBoatHull").FirstOrDefault();waveSprites=JourneySpriteAssets.LoadAll("CrossTheLine/SeaWaveAtlas").OrderBy(s=>s.name).ToArray();if(!hullSprite||waveSprites.Length!=3)throw new Exception("Boat and wave art missing");sleepSprite=JourneySpriteAssets.LoadAll("CrossTheLine/SleepingJesus").FirstOrDefault();if(!sleepSprite)throw new Exception("Sleeping Jesus sprite absent");pixel=g.journeyCamera.GetComponent<UnityEngine.Rendering.Universal.PixelPerfectCamera>();if(pixel){oldPixel=pixel.enabled;pixel.enabled=false;}BuildUI();ConfigureStep(step);}
 Color C(string h){ColorUtility.TryParseHtmlString("#"+h,out var c);return c;}
 Transform Shape(string n,Transform parent,Vector3 p,Vector2 size,string color,int order=0){var o=JourneyObjectFactory.Create(n);o.transform.SetParent(parent,false);o.transform.localPosition=p;o.transform.localScale=new Vector3(size.x,size.y,1);var r=o.GetOrAddComponent<SpriteRenderer>();r.sprite=square;r.sharedMaterial=mat;r.color=C(color);r.sortingOrder=order;return o.transform;}
 Transform Shape(string n,float x,float y,float w,float h,string c,int order=0)=>Shape(n,environment.transform,new Vector3(x,y,0),new Vector2(w,h),c,order);
 Transform Actor(string name,Sprite sprite,Transform parent,float x,float y,float height=1.6f){var o=JourneyObjectFactory.Create(name);o.transform.SetParent(parent,false);o.transform.localPosition=new Vector3(x,y,0);var r=JourneyObjectFactory.Create("Sprite").GetOrAddComponent<SpriteRenderer>();r.transform.SetParent(o.transform,false);r.sprite=sprite;r.sharedMaterial=mat;r.sortingOrder=50;float s=height/sprite.bounds.size.y;r.transform.localScale=Vector3.one*s;r.transform.localPosition=new Vector3(-JourneySpriteAssets.VisibleBounds(sprite).center.x*s,-JourneySpriteAssets.VisibleBounds(sprite).min.y*s,0);return o.transform;}
 public void ConfigureStep(int step){JourneyObjectFactory.BeginStage(this,step);Stage=Mathf.Min(step,4);busy=false;clock=0;lateral=0;velocity=.6f;edgeTime=0;player.SetParent(game.transform,true);if(environment)Destroy(environment);if(sailMesh)Destroy(sailMesh);environment=JourneyObjectFactory.Create("StormSeaEnvironment");environment.transform.SetParent(transform,false);sea=Shape("바다",0,-2,40,15,"6e9caa",-10).GetComponent<SpriteRenderer>();sky=Shape("하늘",0,4.5f,40,5,"d3d5bf",-9).GetComponent<SpriteRenderer>();for(int i=0;i<12;i++){var w=JourneyObjectFactory.Create("흰 포말의 파도 "+i);w.transform.SetParent(environment.transform,false);waves[i]=w.transform;var r=w.GetOrAddComponent<SpriteRenderer>();r.sharedMaterial=mat;r.sprite=waveSprites[0];r.sortingOrder=i<4?20:i<8?60:61;}for(int i=0;i<36;i++)rain[i]=Shape("비바람 "+i,-11+i%12*2,5-i/12*3,.025f,.6f,"a0b8c1",65);
 var o=JourneyObjectFactory.Create("흔들리는 배");o.transform.SetParent(environment.transform,false);boat=o.transform;boat.position=JourneyStageLayout.Point(this,boat,"Placement 1",new Vector3(0,-.6f,0));BuildBoatArt();water=Shape("배에 차오르는 물",boat,new Vector3(0,-.3f,0),new Vector2(9,.04f),"4f93af",54);
 int[] cast={0,1,2,3,4,6};float[] xs={-1.1f,1.25f,2.35f,3.45f,4.55f,Stage==4?.1f:-1.15f};for(int i=0;i<6;i++)disciples[i]=Actor(JourneyGame.ActorNames[cast[i]],game.disciples[cast[i]],boat,xs[i],.07f);disciples[0].gameObject.SetActive(Stage==4);sleeper=Actor("후미에서 주무시는 예수님",sleepSprite,boat,-4,.07f,.8f);awakeJesus=Actor("깨어 바다에 말씀하시는 예수님",game.jesusFrames[0],boat,-4,.07f);player.SetParent(boat,false);player.localRotation=Quaternion.identity;player.localPosition=new Vector3(Stage==4?-4:0,.07f,0);body.transform.localRotation=Quaternion.identity;if(Stage==4)body.flipX=false;var walker=body.GetComponent<DiscipleWalking>();if(walker)walker.enabled=false;
 JesusAwake=Stage>=4;sleeper.gameObject.SetActive(!JesusAwake);awakeJesus.gameObject.SetActive(false);StormStrength=Stage>=1&&Stage<4?1:0;CurrentPhase=Stage==0?Phase.Voyage:Stage==1?Phase.StormRises:Stage==2?Phase.Ready:Stage==3?Phase.Wake:Phase.Quiet;panel.SetActive(false);game.journeyCamera.orthographicSize=5.625f;UpdateCamera();Weather(0);game.BaptismCinema(IsCinematic);Hud();}
 void Rope(string name,Vector3[] points,Color color,float width,int order){var o=JourneyObjectFactory.Create(name);o.transform.SetParent(boat,false);var line=o.GetOrAddComponent<LineRenderer>();line.useWorldSpace=false;line.positionCount=points.Length;line.SetPositions(points);line.startWidth=line.endWidth=width;line.startColor=line.endColor=color;line.sharedMaterial=mat;line.sortingOrder=order;line.numCornerVertices=2;}
 void BuildBoatArt(){var o=JourneyObjectFactory.Create("나뭇결과 곡선 선체");o.transform.SetParent(boat,false);var r=o.GetOrAddComponent<SpriteRenderer>();r.sprite=hullSprite;r.sharedMaterial=mat;r.sortingOrder=35;o.transform.localScale=Vector3.one*(11.6f/hullSprite.bounds.size.x);Shape("갑판 가장자리",boat,new Vector3(0,.035f,0),new Vector2(9.5f,.065f),"bd935a",55);Shape("나무 돛대",boat,new Vector3(2,1.95f,0),new Vector2(.12f,3.9f),"795634",32);Shape("돛대 빛",boat,new Vector3(2.035f,1.95f,0),new Vector2(.025f,3.8f),"b18c59",33);
 var cloth=JourneyObjectFactory.Create("바람에 부푼 천 돛",typeof(MeshFilter),typeof(MeshRenderer));cloth.transform.SetParent(boat,false);sail=cloth.transform;sailMesh=new Mesh();sailMesh.name="BillowedGalileeSail";sailMesh.vertices=new[]{new Vector3(2,1,0),new Vector3(2,3.75f,0),new Vector3(3.15f,3.55f,0),new Vector3(4,3.05f,0),new Vector3(4.4f,2.1f,0),new Vector3(4.2f,1.08f,0),new Vector3(3.15f,.86f,0)};sailMesh.triangles=new[]{0,1,2,0,2,3,0,3,4,0,4,5,0,5,6};sailMesh.uv=Enumerable.Repeat(new Vector2(.5f,.5f),7).ToArray();sailMesh.colors=new[]{C("c3ae84"),C("eadfbc"),C("f2e7c8"),C("eaddb6"),C("d3c199"),C("bca880"),C("e6d6ac")};sailMesh.RecalculateBounds();sailMesh.RecalculateNormals();cloth.GetComponent<MeshFilter>().sharedMesh=sailMesh;var mr=cloth.GetComponent<MeshRenderer>();mr.sharedMaterial=JourneyAssets.Load<Material>("CrossTheLine/SailCanvas");if(!mr.sharedMaterial)throw new Exception("Sail material missing");mr.sortingOrder=31;
 Rope("돛의 천 이음선",new[]{new Vector3(2.12f,3.52f,0),new Vector3(3.35f,2.73f,0),new Vector3(3.72f,1.08f,0)},C("b5a179"),.025f,32);Rope("뱃머리 고정 밧줄",new[]{new Vector3(2,3.9f,0),new Vector3(5.45f,.20f,0)},C("7e7257"),.035f,33);Rope("후미 고정 밧줄",new[]{new Vector3(2,3.9f,0),new Vector3(-5.3f,.12f,0)},C("7e7257"),.035f,33);Rope("돛 하단 밧줄",new[]{new Vector3(2,1,0),new Vector3(4.2f,1.08f,0),new Vector3(5.15f,.12f,0)},C("8c7b5c"),.025f,32);}
 void Hud(){string[] goals={"갈릴리 바다를 건너며 배 후미 살펴보기","몰아치는 풍랑과 배에 차오르는 물","베드로 시점 · 20초 균형을 잡고 버티기","배 후미로 가서 예수님 깨우기","잔잔해진 바다에서 예수님의 말씀 듣기"};game.StormHud(goals[Stage],CurrentPhase==Phase.Quiet?"E · 제자들에게 말씀하기":CurrentPhase==Phase.Balance?"A / D 또는 ← / → · 기울어지는 쪽의 반대로 움직이세요":CurrentPhase==Phase.Failed?"균형을 잃었습니다 · E / R로 다시 도전":CurrentPhase==Phase.Wake?"A / ← · 후미로 이동한 뒤 E로 예수님 깨우기":"E · 이야기 / 균형 게임 시작    A / D · 배 위 이동");}
 void Weather(float dt){float tilt=StormStrength*(Mathf.Sin(clock*1.8f)*13+Mathf.Sin(clock*3.4f)*4);boat.rotation=Quaternion.Euler(0,0,tilt);boat.position=JourneyStageLayout.Point(this,boat,"Placement 2",new Vector3(0,-.6f+StormStrength*Mathf.Sin(clock*2.2f)*.28f,0));sea.color=Color.Lerp(C("6e9caa"),C("294e64"),StormStrength);sky.color=Color.Lerp(C("d3d5bf"),C("5d6878"),StormStrength);for(int i=0;i<12;i++){int layer=i/4;var r=waves[i].GetComponent<SpriteRenderer>();r.sprite=waveSprites[StormStrength<.25f?0:layer==0?1:2];float width=layer==0?6.8f:layer==1?6.3f:7.2f;float scale=width/r.sprite.bounds.size.x;waves[i].localScale=new Vector3(scale,scale*Mathf.Lerp(.42f,layer==0?.78f:.64f,StormStrength),1);float x=-13+Mathf.Repeat(clock*(.3f+StormStrength*(.7f+layer*.35f))+i%4*6.7f+layer*1.4f,27);float y=(layer==0?-2.4f:layer==1?-3.9f:-5.6f)+Mathf.Sin(clock*(1.3f+layer*.3f)+i*.9f)*StormStrength*.24f;waves[i].position=JourneyStageLayout.Point(this,waves[i],"Placement 3",new Vector3(x,y,0));r.color=layer==0?new Color(.67f,.84f,.91f,.8f):Color.white;waves[i].rotation=Quaternion.identity;}if(sail)sail.localRotation=Quaternion.Euler(0,0,Mathf.Sin(clock*2.7f)*StormStrength*2);for(int i=0;i<36;i++){rain[i].gameObject.SetActive(StormStrength>.1f);rain[i].position=JourneyStageLayout.Point(this,rain[i],"Placement 4",new Vector3(-11+i%12*2-Mathf.Repeat(clock*2+i*.1f,2),5-Mathf.Repeat(clock*4+i*.73f,10),0));rain[i].rotation=Quaternion.Euler(0,0,-25);}float fill=StormStrength*(.07f+(Stage==2?Survived/SurviveDuration*.55f:.25f));water.localScale=new Vector3(9,fill,1);water.localPosition=new Vector3(0,-.4f+fill*.5f,0);for(int i=1;i<6;i++){var b=disciples[i].GetChild(0);b.localRotation=Quaternion.Euler(0,0,-tilt*.45f+StormStrength*Mathf.Sin(clock*7+i)*4);}}
 public void Tick(float dt,bool canMove,bool press){if(!canMove&&!IsCinematic)return;clock+=dt;if(CurrentPhase==Phase.StormRises){StormStrength=Mathf.Clamp01(clock/3);Weather(dt);if(clock>=3.5f)game.BaptismAdvance();return;}if(CurrentPhase==Phase.Calming){StormStrength=Mathf.Clamp01(1-clock/3);Weather(dt);if(clock>=3.2f)game.BaptismAdvance();return;}Weather(dt);if(CurrentPhase==Phase.Balance){var k=Keyboard.current;float input=k==null?0:(k.dKey.isPressed||k.rightArrowKey.isPressed?1:0)-(k.aKey.isPressed||k.leftArrowKey.isPressed?1:0);Balance(dt,input);return;}if(CurrentPhase==Phase.Failed){if(press||(Keyboard.current!=null&&Keyboard.current.rKey.wasPressedThisFrame))Retry();return;}if(!canMove||busy)return;var keyboard=Keyboard.current;float x=keyboard==null?0:(keyboard.dKey.isPressed||keyboard.rightArrowKey.isPressed?1:0)-(keyboard.aKey.isPressed||keyboard.leftArrowKey.isPressed?1:0);if(Stage!=4){var p=player.localPosition;p.x=Mathf.Clamp(p.x+x*dt*3.2f,-4.6f,4.6f);player.localPosition=p;game.MeetingWalk(x!=0,x);}Hud();if(press)Interact();}
 public void Balance(float dt,float input){if(CurrentPhase!=Phase.Balance)return;float wind=(Mathf.Sin(clock*1.8f)*1.6f+Mathf.Sin(clock*3.4f)*.5f+.38f);velocity+=(wind+Mathf.Clamp(input,-1,1)*3.6f-velocity*.45f)*dt;lateral+=velocity*dt;Survived+=dt;player.localPosition=new Vector3(Mathf.Clamp(lateral,-4.8f,4.8f),.07f,0);game.MeetingWalk(Mathf.Abs(input)>.1f,input);body.transform.localRotation=Quaternion.Euler(0,0,-Mathf.DeltaAngle(0,boat.eulerAngles.z)*.18f);edgeTime=Mathf.Abs(lateral)>3.7f?edgeTime+dt:Mathf.Max(0,edgeTime-dt*2);marker.anchorMin=new Vector2(Mathf.Clamp01((lateral+4.8f)/9.6f),0);marker.anchorMax=marker.anchorMin+new Vector2(.015f,1);timeFill.anchorMax=new Vector2(.07f+.86f*Mathf.Clamp01(Survived/SurviveDuration),.25f);feedback.text="버티기 "+Mathf.CeilToInt(SurviveDuration-Survived)+"초 남음 · "+(edgeTime>.2f?"위험! 가운데로 돌아오세요":"A / D로 균형 잡기");if(edgeTime>=1.15f){CurrentPhase=Phase.Failed;feedback.text="균형을 잃었습니다 · E / R로 다시 도전";Hud();}else if(Survived>=SurviveDuration){panel.SetActive(false);game.BaptismAdvance();}}
 public void Retry(){if(CurrentPhase!=Phase.Failed)return;Retries++;StartBalance();}
 void StartBalance(){CurrentPhase=Phase.Balance;clock=0;lateral=0;velocity=.6f;edgeTime=0;Survived=0;player.localPosition=new Vector3(0,.07f,0);panel.SetActive(true);Hud();}
 public void Interact(){if(busy||IsCinematic||InGame)return;if(CurrentPhase==Phase.Wake&&player.localPosition.x>-2.8f)return;busy=true;game.MeetingTalk(()=>{busy=false;if(Stage==2)StartBalance();else if(Stage==3){JesusAwake=true;sleeper.gameObject.SetActive(false);awakeJesus.gameObject.SetActive(true);CurrentPhase=Phase.Calming;clock=0;game.BaptismCinema(true);}else game.BaptismAdvance();});}
 void BuildUI(){var o=JourneyObjectFactory.Create("StormBalanceUI",typeof(RectTransform),typeof(Canvas),typeof(CanvasScaler));o.transform.SetParent(transform,false);ui=o.GetComponent<Canvas>();ui.renderMode=RenderMode.ScreenSpaceOverlay;ui.sortingOrder=90;var s=o.GetComponent<CanvasScaler>();s.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;s.referenceResolution=new Vector2(1440,900);panel=Box(o.transform,"균형 게임",new Vector2(.55f,.13f),new Vector2(.96f,.32f),C("e9dcc0")).gameObject;var track=Box(panel.transform,"배 위 위치",new Vector2(.07f,.40f),new Vector2(.93f,.51f),C("975c50"));Box(track,"안전한 가운데",new Vector2(.17f,0),new Vector2(.83f,1),C("6a966d"));marker=Box(track,"베드로 위치",new Vector2(.5f,0),new Vector2(.515f,1),C("e7bf5d"));timeFill=Box(panel.transform,"버틴 시간",new Vector2(.07f,.17f),new Vector2(.07f,.25f),C("568c9b"));var text=JourneyObjectFactory.Create("안내",typeof(RectTransform));text.transform.SetParent(panel.transform,false);var r=text.GetComponent<RectTransform>();r.anchorMin=new Vector2(.07f,.60f);r.anchorMax=new Vector2(.93f,.96f);r.offsetMin=r.offsetMax=Vector2.zero;feedback=text.GetOrAddComponent<TextMeshProUGUI>();feedback.font=game.koreanFont;feedback.fontSize=18;feedback.color=C("344e4d");}
 RectTransform Box(Transform p,string n,Vector2 min,Vector2 max,Color c){var o=JourneyObjectFactory.Create(n,typeof(RectTransform),typeof(Image));o.transform.SetParent(p,false);var r=o.GetComponent<RectTransform>();r.anchorMin=min;r.anchorMax=max;r.offsetMin=r.offsetMax=Vector2.zero;o.GetComponent<Image>().color=c;return r;}
 void LateUpdate(){if(ui)ui.enabled=game.Mode!="menu"&&game.Mode!="dialogue"&&game.Mode!="chapter_end";}
 public void UpdateCamera(){game.journeyCamera.transform.position=JourneyStageLayout.Point(this,game.journeyCamera.transform,"Placement 5",new Vector3(0,0,-10));}
 public void Shutdown(){if(shutdown)return;shutdown=true;if(player&&game)player.SetParent(game.transform,true);if(pixel)pixel.enabled=oldPixel;if(sailMesh)Destroy(sailMesh);}
 void OnDestroy(){if(shutdown)return;shutdown=true;if(pixel)pixel.enabled=oldPixel;if(sailMesh)Destroy(sailMesh);}
}
